const crypto = require('node:crypto');
const { ActionAgentExecutor } = require('./action_agent_executor');
const { runCommand, runCommandInWindow } = require('./action_command_executor');
const { ActionDefinitionCache } = require('./action_definition_cache');
const { resolveActionDefinition } = require('./action_definition_resolver');
const { ActionRun } = require('./action_run');
const { appendCurrentCardReferences } = require('./action_card_references');
const { createDiagramPath, resolveDiagramFile } = require('./action_diagram_output');
const { resolveAgentPrompt } = require('./action_text');
const { validatePreparePromptRequest, validateStartRequest } = require('./action_run_request');
const { assertReleasedCardActionAllowed } = require('../../../../shared/released_card_actions.mjs');
const { parseConversationActivityReference } = require('../../../../shared/activity_paths.mjs');

function createRunId() {
    return `action-${crypto.randomUUID()}`;
}

const TERMINAL_RECOVERY_RETENTION_MS = 5 * 60 * 1000;

// Activity ownership follows the presence of cardInternalId, not the context kind.
function activityOrigin(context) {
    if (typeof context.cardInternalId === 'string' && context.cardInternalId.length > 0) {
        return { cardInternalId: context.cardInternalId, kind: 'card' };
    }

    return { kind: 'project' };
}

function requireConfiguredStates(states) {
    if (!Array.isArray(states)) throw new Error('Invalid project states');

    return states.map(({ state }) => {
        if (typeof state !== 'string' || state.length === 0) throw new Error('Invalid project state');

        return state;
    });
}

function hasStreamingAction(action, visited = new Set()) {
    if (visited.has(action.id)) return false;
    visited.add(action.id);
    if (action.type === 'agent' && action.streaming) return true;

    return [...action.onBefore, ...action.onAfter, ...action.on.map(({ action: linkedAction }) => linkedAction)]
        .some((linkedAction) => hasStreamingAction(linkedAction, visited));
}

class ActionRunnerService {
    constructor(dependencies) {
        this.actionWorktreeRunService = dependencies?.actionWorktreeRunService;
        this.agentConfigProvider = dependencies?.agentConfigProvider;
        this.agentRunnerService = dependencies?.agentRunnerService;
        this.commandRunner = dependencies?.commandRunner ?? runCommand;
        this.commandWindowRunner = dependencies?.commandWindowRunner ?? runCommandInWindow;
        this.diagramOutputWatcherFactory = dependencies?.diagramOutputWatcherFactory;
        this.errorReporter = dependencies?.errorReporter ?? (() => undefined);
        this.localGitService = dependencies?.localGitService;
        this.now = dependencies?.now ?? Date.now;
        this.usageMetricsService = dependencies?.usageMetricsService ?? null;
        this.actionDefinitionCache = dependencies?.actionDefinitionCache
            ?? (this.localGitService ? new ActionDefinitionCache({ localGitService: this.localGitService }) : null);
        this.agentExecutor = new ActionAgentExecutor({
            agentConfigProvider: this.agentConfigProvider,
            agentRunnerService: this.agentRunnerService,
            localGitService: this.localGitService,
        });
        this.actionsFolder = null;
        this.activeCardsFolder = null;
        this.actionCacheReady = null;
        this.completedRunResults = new Map();
        this.recoveryRunResults = new Map();
        this.conversationReservations = new Map();
        this.configuredStates = [];
        this.diagramFooter = null;
        this.diagramsFolder = null;
        this.latestDiagramTimestampMs = 0;
        this.runEvents = new Map();
        this.runs = new Map();
        this.listeners = new Set();
        this.project = null;
        this.projectFolder = null;
        this.releasesFolder = null;
        this.restartingRuns = new Set();
    }

    // Paths arrive already resolved and validated from resolveProjectPaths, and states from the same
    // config read, so the runner no longer loads `.md2/config` it
[10602 characters omitted]
tate);
    }

    requireActionsFolder() {
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');
        if (!this.activeCardsFolder) throw new Error('Action runner has no activeCardsFolder');

        return this.actionsFolder;
    }

    requireProjectFolder() {
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (!this.diagramsFolder) throw new Error('Action runner has no diagramsFolder');
        if (!this.diagramFooter) throw new Error('Action runner has no diagramFooter');
        if (this.releasesFolder === null) throw new Error('Action runner has no releasesFolder');

        return this.projectFolder;
    }

    async loadRootAction(actionId) {
        const config = this.agentConfigProvider();
        await this.actionCacheReady;

        return resolveActionDefinition(this.actionDefinitionCache, config.agentProfiles, actionId, this.configuredStates);
    }

    allocateDiagramPath(actionLabel) {
        const timestampMs = Math.max(this.now(), this.latestDiagramTimestampMs + 1);
        this.latestDiagramTimestampMs = timestampMs;

        return createDiagramPath(actionLabel, this.diagramsFolder, timestampMs);
    }

    resolveStartDiagramPath(startRequest, rootAction) {
        if (rootAction.output?.kind !== 'diagram') {
            if (startRequest.runInput.diagramPath !== undefined) {
                throw new Error('Diagram output path requires a diagram action');
            }

            return null;
        }

        if (startRequest.context.kind !== 'diagram') throw new Error('Diagram action requires diagram context');

        return startRequest.runInput.diagramPath ?? this.allocateDiagramPath(rootAction.label);
    }

    async finalizeRun(run, runCompletion) {
        const result = await runCompletion;
        this.runs.delete(run.runId);
        this.runEvents.delete(run.runId);
        this.completedRunResults.set(run.runId, result);
        this.recoveryRunResults.set(run.runId, {
            expiresAt: Date.now() + TERMINAL_RECOVERY_RETENTION_MS,
            result,
        });
        return result;
    }

    publish(event) {
        const events = this.runEvents.get(event.runId);
        if (events) events.push(event);
        for (const listener of this.listeners) {
            try {
                listener(event);
            } catch (error) {
                this.reportError(error);
            }
        }
    }

    reportError(error) {
        try {
            this.errorReporter(error);
        } catch {
            // Error reporting must not affect action runs.
        }
    }

    /** Reports every in-flight run so a release can refuse to start while agents are working. */
    listActiveRuns() {
        return [...this.runs.values()].map((run) => ({ label: run.rootAction.label, runId: run.runId }));
    }

    requireRun(runId) {
        const run = this.runs.get(runId);
        if (!run) throw new Error(`Unknown action run: ${runId}`);

        return run;
    }

    requireReady() {
        this.requirePreparationReady();
        if (!this.agentRunnerService) throw new Error('Action runner has no agent runner service');
    }

    requirePreparationReady() {
        if (!this.project) throw new Error('Action runner has no project');
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (!this.localGitService) throw new Error('Action runner has no local Git service');
        if (!this.actionDefinitionCache) throw new Error('Action runner has no action definition cache');
        if (!this.actionCacheReady) throw new Error('Action runner action definition cache is not ready');
        if (!this.actionWorktreeRunService) throw new Error('Action runner has no worktree run service');
        if (!this.agentConfigProvider) throw new Error('Action runner has no agent config provider');
    }
}

module.exports = { ActionRunnerService };

import type { ActionContext } from '../app/src/data/action_context'

export const ACTION_SCHEDULES_FILE: '.md2-schedules.json'

export type ScheduleStatus = 'cancelled' | 'completed' | 'failed' | 'pending' | 'running'

export interface NowScheduleTrigger {
    type: 'now'
}

export interface AtScheduleTrigger {
    timestamp: string
    type: 'at'
}

export interface AccountResetScheduleTrigger {
    agent: string
    expectedResetAt: string
    limitId: string
    type: 'account-reset'
    windowId: string
}

export interface CardStateScheduleTrigger {
    cardInternalId: string
    registrationState: string
    targetState: string
    type: 'card-state'
}

export type ScheduleTrigger = NowScheduleTrigger | AtScheduleTrigger | AccountResetScheduleTrigger | CardStateScheduleTrigger
export type ActionScheduleTrigger = Exclude<ScheduleTrigger, NowScheduleTrigger>

interface ScheduleBase {
    createdAt: string
    id: string
    status: ScheduleStatus
    trigger: ScheduleTrigger
}

export interface ActionSchedule extends ScheduleBase {
    actionId: string
    context: ActionContext
    kind: 'action'
    trigger: ActionScheduleTrigger
}

export interface SequenceSchedule extends ScheduleBase {
    cardInternalIds: string[]
    kind: 'sequence'
}

export type Schedule = ActionSchedule | SequenceSchedule

export interface ScheduleFile {
    schedules: Schedule[]
}

export function parseScheduleFile(value: unknown): ScheduleFile
export function createScheduleFile(schedules: Schedule[]): ScheduleFile

export const ACTION_SCHEDULES_FILE = '.md2-schedules.json';

const SCHEDULE_STATUSES = new Set(['cancelled', 'completed', 'failed', 'pending', 'running']);
const ACTION_CONTEXT_KINDS = new Set(['card', 'diagram', 'file', 'folder', 'merge-conflict', 'project']);

function requireObject(value, fieldName) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error(`Invalid schedule file: ${fieldName} must be an object`);
    }

    return value;
}

function requireString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Invalid schedule file: missing ${fieldName}`);

    return value;
}

function requireTimestamp(value, fieldName) {
    const timestamp = requireString(value, fieldName);
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Invalid schedule file: invalid ${fieldName}`);

    return timestamp;
}

function parseContext(value) {
    const context = requireObject(value, 'context');
    const kind = requireString(context.kind, 'context.kind');
    if (!ACTION_CONTEXT_KINDS.has(kind)) throw new Error(`Invalid schedule file: unsupported context kind ${kind}`);
    const parsedContext = { kind };

    for (const [key, contextValue] of Object.entries(context)) {
        if (key === 'kind') continue;
        if (typeof contextValue !== 'string') throw new Error(`Invalid schedule file: context.${key} must be a string`);
        parsedContext[key] = contextValue;
    }

    return parsedContext;
}

function parseTrigger(value) {
    const trigger = requireObject(value, 'trigger');
    const type = requireString(trigger.type, 'trigger.type');

    if (type === 'now') return { type };
    if (type === 'at') return { timestamp: requireTimestamp(trigger.timestamp, 'trigger.timestamp'), type };
    if (type === 'account-reset') {
        return {
            agent: requireString(trigger.agent, 'trigger.agent'),
            expectedResetAt: requireTimestamp(trigger.expectedResetAt, 'trigger.expectedResetAt'),
            limitId: requireString(trigger.limitId, 'trigger.limitId'),
            type,
            windowId: requireString(trigger.windowId, 'trigger.windowId'),
        };
    }
    if (type === 'card-state') {
        return {
            cardInternalId: requireString(trigger.cardInternalId, 'trigger.cardInternalId'),
            registrationState: requireString(trigger.registrationState, 'trigger.registrationState'),
            targetState: requireString(trigger.targetState, 'trigger.targetState'),
            type,
        };
    }

    throw new Error(`Invalid schedule file: unsupported trigger type ${type}`);
}

function parseStatus(value) {
    const status = requireString(value, 'status');
    if (!SCHEDULE_STATUSES.has(status)) throw new Error(`Invalid schedule file: unsupported status ${status}`);

    return status;
}

function parseBaseSchedule(value) {
    const schedule = requireObject(value, 'schedule');
    const kind = requireString(schedule.kind, 'kind');
    if (kind !== 'action' && kind !== 'sequence') throw new Error(`Invalid schedule file: unsupported kind ${kind}`);

    return {
        createdAt: requireTimestamp(schedule.createdAt, 'createdAt'),
        id: requireString(schedule.id, 'id'),
        kind,
        status: parseStatus(schedule.status),
        trigger: parseTrigger(schedule.trigger),
    };
}

function parseActionSchedule(schedule, base) {
    if (base.trigger.type === 'now') throw new Error('Invalid schedule file: now trigger requires sequence kind');
    const context = parseContext(schedule.context);
    if (base.trigger.type === 'card-state' && context.cardInternalId === base.trigger.cardInternalId) {
        throw new Error('Invalid schedule file: scheduled action card and trigger card must differ');
    }

    return { actionId: requireString(schedule.actionId, 'actionId'), context, ...base };
}

function parseCardInternalIds(value) {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Invalid schedule file: cardInternalIds must be a non-empty array');
    const cardInternalIds = value.map((cardInternalId, index) => requireString(cardInternalId, `cardInternalIds[${index}]`));
    if (new Set(cardInternalIds).size !== cardInternalIds.length) {
        throw new Error('Invalid schedule file: duplicate sequence cardInternalId');
    }

    return cardInternalIds;
}

function parseSequenceSchedule(schedule, base) {
    return { cardInternalIds: parseCardInternalIds(schedule.cardInternalIds), ...base };
}

function parseSchedule(value) {
    const schedule = requireObject(value, 'schedule');
    const base = parseBaseSchedule(schedule);

    return base.kind === 'action'
        ? parseActionSchedule(schedule, base)
        : parseSequenceSchedule(schedule, base);
}

/** Parse and validate persisted schedule JSON. */
export function parseScheduleFile(value) {
    const file = requireObject(value, 'root');
    if (!Array.isArray(file.schedules)) throw new Error('Invalid schedule file: schedules must be an array');

    return { schedules: file.schedules.map(parseSchedule) };
}

/** Build persisted schedule JSON after validating every record. */
export function createScheduleFile(schedules) {
    return parseScheduleFile({ schedules });
}

